    assertEquals(encl(0x8000000000000001l), (long) AccumuloStore.followingKey(encoder, Long.class, new byte[] { (byte) 0x80, 0, 0, 0, 0, 0, 0, 0 }));
    assertEquals(encl(0x8000000000000000l), (long) AccumuloStore.followingKey(encoder, Long.class, new byte[] { (byte) 0x7f, (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff, (byte) 0xff }));
